mkdir -p /tmp/ssr && cat > /tmp/ssr/check.mjs <<'EOF'
import { createServer } from 'vite';
const root = process.argv[2];
const s = await createServer({ root, server: { middlewareMode: true }, appType: 'custom', logLevel: 'error' });
const React = (await s.ssrLoadModule('react')).default;
const { renderToString } = await s.ssrLoadModule('react-dom/server');
const { App } = await s.ssrLoadModule('/src/App.tsx');
const html = renderToString(React.createElement(App));
console.log('len', html.length);
console.log('data-theme:', html.match(/data-theme="[a-z]+"/g));
console.log('paths:', (html.match(/line-chart__line/g)||[]).length, 'end labels:', (html.match(/line-chart__end-label/g)||[]).length);
await s.close();
EOF
